from typing import List, Tuple

class Pair:
    def __init__(self, start: int, end: int):
        self.start = start
        self.end = end

def max_chain_length(pairs: List[Pair], n: int) -> int:
    # Sort the pairs by their ending values
    pairs.sort(key=lambda x: x.end)

    ans, prev_end = 0, -float('inf')
    for i in range(n):
        if pairs[i].start > prev_end:
            ans += 1
            prev_end = pairs[i].end

    return ans

