def prime_num(n):
    """Check if the given integer is a prime number."""
    # Handle edge cases for numbers less than 2 and negative values
    if n <= 1 or (n > 2 and n % 2 == 0):
        return False

    # Check divisors from 3 up to sqrt(n)
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2

    return True

