def max_occurrences(arr):
    # Create a dictionary to count the frequency of each element in arr
    freq_dict = {}
    for i in range(len(arr)):
        if arr[i] not in freq_dict:
            freq_dict[arr[i]] = 0
        freq_dict[arr[i]] += 1

    # Find the key (item) with the highest value (frequency)
    max_freq_item = ''
    max_freq_value = float('-inf')
    for key, value in freq_dict.items():
        if value > max_freq_value:
            max_freq_value = value
            max_freq_item = key

    return max_freq_item

