def Repeat(lst):
    # Dictionary to store counts of each number
    dict = {}

    # Iterate through the list
    for i in lst:
        if i in dict:
            dict[i] += 1
        else:
            dict[i] = 1

    # List to hold duplicate numbers
    res = []

    # Check each key-value pair in the dictionary
    for k, v in dict.items():
        # If count is greater than 1, it means there are duplicates
        if v > 1:
            res.append(k)

    return res

