import math

def count_Fac(n):
    # Function to find the largest prime factor
    def max_prime_factor(x):
        i = 2
        while x % i != 0:
            i += 1
        return i

    # Initialize variables to store total distinct primes and their counts
    distinct_primes = []
    prime_counts = {}

    # Function to extract the largest prime factor
    def extract_largest_prime_factors(x):
        for num in range(max_prime_factor(x), int(math.sqrt(x)) - 1, -1):
            if x % num == 0:
                distinct_primes.append(num)
                prime_counts[num] = 1 if num not in prime_counts else prime_counts[num] + 1
                break

    # Factorize n by trial division
    for i in range(2, n + 1):
        if n % i == 0:
            extract_largest_prime_factors(i)
            n //= i

    return len(distinct_primes)

