    """
    This function checks if the given string expression has all types of brackets: 
    curly {}, square [], and parenthesis (). It returns True if the expression is balanced, False otherwise.

    Args:
        expression (str): The string expression containing brackets.

    Returns:
        bool: True for balanced brackets, False for unbalanced brackets.
    """

    # Dictionary to store bracket pairs
    bracket_pairs = {')': '(', ']': '[', '}': '{'}

    stack = []

    for char in expression:
        if char in bracket_pairs.values():
            stack.append(char)
