def count_Pairs(arr, N):
    # Dictionary to store the frequency of each element
    dic = {}

    # Counting frequencies of each element
    for i in arr:
        if i in dic.keys():
            dic[i] += 1
        else:
            dic[i] = 1

    # Calculating the number of pairs for each unique element
    ans = []
    for key, val in dic.items():
        if val > 1:  # Only consider elements with more than one occurrence
            ans.append(val * (val - 1) // 2)

    # Summing up all the pair counts
    return sum(ans)

