def get_primes(divisor):
    """Get all prime factors of a given divisor."""
    primes = []
    while divisor > 1:
        # Find the smallest prime factor greater than or equal to 2
        smallest_prime = 2
        while smallest_prime * smallest_prime <= divisor:
            if divisor % smallest_prime == 0:
                primes.append(smallest_prime)
                divisor //= smallest_prime
                break
            else:
                smallest_prime += 1
    return primes

def Sum(number):
    """
    This function takes an integer 'number' as input and returns the sum of its prime divisors.

    Args:
    - number: An integer whose prime divisors need to be summed.

    Returns:
    - The sum of all prime divisors of the given number.
    """
    sum_of_divisors = 0
    current_number = number

    # Iterate over possible divisors starting from 2 up to the square root of number
    for divisor in range(2, int(number**0.5) + 1):
        if current_number % divisor == 0 and is_prime(divisor):
            sum_of_divisors += divisor
            # Ensure to divide by the duplicate copy of the prime
            while current_number % divisor == 0:
                current_number //= divisor

    # If there's any remaining number left which is a prime (which was not found in previous iterations),
    # add it to the sum
    if current_number > 1 and is_prime(current_number):
        sum_of_divisors += current_number

    return sum_of_divisors

