def Sum(n):
    # Initialize sum to 0
    result = 0

    # Check for divisibility by 2 and skip even numbers after first iteration
    if n % 2 == 0: 
        result += 2
        while n % 2 == 0: 
            n //= 2

    # Check for odd factors from 3 onwards, up to sqrt(n)
    i = 3
    while i * i <= n: 
        if n % i == 0: 
            result += i 
            while n % i == 0: 
                n //= i
        i += 2

    # If n is still greater than 2, it's a prime number
    if n > 2: 
        result += n

    return result

