def gcd(a, b):
    # Base case: if b is zero, GCD is a
    if b == 0:
        return a
    else:
        # Recursive call with parameters swapped and one less step
        return gcd(b, a % b)

def lcm(x, y):
    # Calculate the greatest common divisor using the Euclidean algorithm
    gcd_value = gcd(x, y)

    # Return the product of x and y divided by their GCD
    return abs(x * y) // gcd_value

