def is_Isomorphic(s, t):
    # If lengths of both strings are different, they can't be isomorphic
    if len(s) != len(t):
        return False

    # Create dictionaries for character mapping from s and t
    map_s = {}
    map_t = {}

    # Iterate through each character pair
    for i in range(len(s)):
        char1 = s[i]
        char2 = t[i]

        # Check if characters already mapped
        if char1 in map_s and map_s[char1] != char2:
            return False

        if char2 in map_t and map_t[char2] != char1:
