def max_sum_subseq(nums):
    # Check if there is at least one number in the list
    if not nums or len(nums) == 0:
        return None

    # Handle edge case where all numbers are negative
    elif all(x < 0 for x in nums):
        return min(nums)

    # Initialize DP table
    dp = [0] * (len(nums))
    dp[0], dp[1] = nums[0], max(nums[0], nums[1])

    # Fill the DP table
    for i in range(2, len(dp)):
        dp[i] = max(dp[i-1], dp[i-2] + nums[i])

    # The last entry will contain the result
    return dp[-1]

def max_sum_subseq(arr):
    if not arr:
        return 0

    n = len(arr)
    dp = [0] * n
    dp[0] = arr[0]
    dp[1] = max(arr[0], arr[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], dp[i-2] + arr[i])

    return dp[-1]

