def coin_change(arr, n, s):
    dp = [0 for _ in range(s + 1)]

    # Base cases
    dp[0] = 1

    for i in range(n):
        for j in range(1, s + 1):
            if j >= arr[i]:
                dp[j] += dp[j - arr[i]]

    return dp[s]

