def max_char(s):
    char_count = {}

    # Count characters in the string
    for char in s:
        if char not in char_count:
            char_count[char] = 0
        char_count[char] += 1

    # Find the character with the highest count
    max_count = -1
    max_char = ''
    for char, count in char_count.items():
        if count > max_count:
            max_count = count
            max_char = char

    return max_char

