def subset(nums, target):
    n = len(nums)

    # Initialize the DP table
    dp = [float('inf')] * (target + 1)
    dp[0] = 0  # Base case: zero is always included

    # Fill the DP table
    for i in range(1, target + 1):
        for num in nums:
            if num <= i and dp[i - num] != float('inf'):
                dp[i] = min(dp[i], dp[i - num] + 1)

    return dp[target]

