def roman_to_int(s):
    # Define the values of each Roman numeral symbol
    value_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

    result = 0

    # Iterate through the string from left to right
    for i in range(len(s)):
        # Check if the current and next symbols form a subtractive pair (e.g., IV)
        if i + 1 < len(s) and value_map[s[i]] < value_map[s[i+1]]:
            result -= value_map[s[i]]
        else:
            result += value_map[s[i]]

    return result

def roman_to_int(s):
    d = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    result, prev_value = 0, 0

    for char in reversed(s):
        value = d[char]
        if value < prev_value:
            result -= value
        else:
            result += value
        prev_value = value

    return result

