def get_lcm(nums):
    def gcd(a, b):
        while b != 0:
            t = b
            b = a % b
            a = t
        return a

    lcm = nums[0]
    for i in range(1, len(nums)):
        lcm = (nums[i] * lcm) // gcd(lcm, nums[i])
    return lcm

