def check_permutation(str1, str2):
    """
    Checks if two given strings are permutations of each other.

    Args:
        str1 (str): First string.
        str2 (str): Second string.

    Returns:
        bool: True if the strings are permutations of each other, False otherwise.
    """

    # If lengths differ, they cannot be permutations
    if len(str1) != len(str2):
        return False

    char_count = {}

    # Count characters in the first string
    for char in str1:
        char_count[char] = char_count.get(char, 0) + 1

    # Decrease character count for every matching character found in the second string
    for char in str2:
        if char in char_count and char_count[char] > 0:
            char_count[char] -= 1
        else:
            # Return False immediately if any character is not present or matched in both strings
            return False

    # Check if all counts are zero indicating that chars were matched perfectly
    return all(count == 0 for count in char_count.values())

