def find_Diff(arr, n):
    # Dictionary to count the frequency of each element
    freq = {}

    # Populate the frequency dictionary
    for i in arr:
        if i in freq:
            freq[i] += 1
        else:
            freq[i] = 1

    # Initialize max and min with the first value found
    max_freq = min_freq = freq[arr[0]]

    # Iterate through the remaining elements to update max and min frequencies
    for j in range(1, len(freq)):
        if freq[arr[j]] > max_freq:
            max_freq = freq[arr[j]]
        elif freq[arr[j]] < min_freq:
            min_freq = freq[arr[j]]

    # Return the difference between max and min frequencies
    return (max_freq - min_freq)

