def longest_increasing_subsequence(sequence):
    # Initialize variables for dynamic programming
    n = len(sequence)
    dp = [1] * n  # Base case: each element is an increasing subsequence of length 1

    # Fill the dp array with the lengths of increasing subsequences ending at each index
    for i in range(1, n):
        for j in range(i):
            if sequence[i] > sequence[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the longest increasing subsequence is the maximum value in dp
    return max(dp)

def find_Max(nums, l, r):
    # If there is only one element, return it as the maximum
    if l == r:
        return nums[l]

    # Calculate the middle index
    mid = (l + r) // 2

    # Check if the middle element is greater than the rightmost element
    if mid < r and nums[mid] > nums[mid + 1]:
        return nums[mid]
    # Check if the leftmost element is greater than the middle element
    elif mid > l and nums[l] > nums[mid]:
        return nums[l]
    # Otherwise, the maximum must be on the right half
    else:
        return find_Max(nums, mid + 1, r)

