def find_Odd_Pair(A, n):
    # Initialize result counter
    cnt = 0

    # Iterate through all possible pairs
    for i in range(n - 1):
        for j in range(i + 1, n):
            if (A[i] ^ A[j]) % 2 != 0:  # Check if xor of pair is odd
                cnt += 1

    return cnt

