def digit_distance_nums(x: int, y: int) -> int:
    # Convert numbers to strings and split them into individual digits
    x_digits = [int(digit) for digit in str(abs(x))]
    y_digits = [int(digit) for digit in str(abs(y))]

    # Calculate the absolute difference between corresponding digits of both numbers
    return sum([abs(a - b) for a, b in zip(x_digits, y_digits)])

