def union_elements(*args):
    # Convert all arguments into lists and then concatenate them
    concatenated_list = [element for sublist in args for element in sublist]

    # Use set comprehension to remove duplicates while preserving order
    unique_elements = {element for element in concatenated_list}

    return tuple(unique_elements)

# Test the function with the provided test case
assert union_elements((3, 4, 5, 6), (5, 7, 4, 10)) == (3, 4, 5, 6, 7, 10)

def Find_Max_Length(lst):
    max_length = 0
    for i in range(len(lst)):
        current_max = 0
        for j in lst[i]:
            if type(j) is list:
                current_max += 1 + Find_Max_Length(j)
            else:
                current_max += 1
        max_length = max(max_length, current_max)
    return max_length

import re

def extract_values(s):
    # Use regular expression to find all substrings within double quotes
    return re.findall(r'"(.*?)"', s)

