def sort_sublists(lst):
    # Map each sublist to a sorted version
    return [sorted(sublist) for sublist in lst]

def sort_sublists(list_of_lists):
    # Use map() with key argument and lambda to apply the sorted() function on each sublist
    return list(map(sorted, list_of_lists))

def unique_product(arr):
    import functools

    # Calculate the product of all elements and then divide by the product of duplicates
    return functools.reduce(lambda x, y: x * y, set(arr), 1)

def is_Sub_Array(arr1, arr2, len1, len2):
    # If lengths do not match, it cannot be a subarray
    if len1 != len2:
        return False

    # Use two pointers for each array
    ptr1 = 0  # Pointer for first array
    ptr2 = 0  # Pointer for second array

    # Iterate until either pointer goes out of bounds
    while (ptr1 < len1 and ptr2 < len2):
        # Check if elements match at current positions
        if arr1[ptr1] == arr2[ptr2]:
            ptr1 += 1  # Move forward in first array
            ptr2 += 1  # Move forward in second array
        else:
            ptr1 -= 1  # Backtrack in first array

        # If no match found, backtrack
        if ptr1 >= ptr2:
            break

    # Check if all elements were matched
    if ptr1 < len1 and ptr2 < len2:
        return True
    else:
        return False

# Test the function with provided data point
assert is_Sub_Array([1,4,3,5],[1,2],4,2) == False

def last_Digit_Factorial(n):
    # Calculate n!
    fact = 1
    for i in range(2, n + 1):
        fact *= i

    # Return the last digit of the factorial
    return int(fact % 10)

def interleave_lists(*lists):
    """
    Interleaves elements from multiple lists of equal length.

    Parameters:
    *lists (List): Variable number of lists to be interleaved

    Returns:
    List: A new list with elements from each input list interleaved
    """

    # Check if all lists have the same length
    if len(set(map(len, lists))) > 1:
        raise ValueError("All provided lists must be of equal length")

    result = []
    for i in range(len(lists[0])):
        for j in range(len(lists)):
            try:
                result.append(lists[j][i])
            except IndexError:
                break
    return result

def find_dissimilar(tup1, tup2):
    # Remove duplicates from both tuples by converting them into sets and then back into lists
    unique_elements = list(set(tup1) ^ set(tup2))
    return tuple(unique_elements)

def find_dissimilar(tuple1, tuple2):
    # Create sets from both tuples and compute their symmetric difference
    return tuple(set(tuple1).symmetric_difference(set(tuple2)))

# Test the function with the provided data point
assert find_dissimilar((3, 4, 5, 6), (5, 7, 4, 10)) == (3, 6, 7, 10)

def find_dissimilar(a, b):
    # Find all unique elements from both tuples and return them as a tuple
    return tuple(set(a) ^ set(b))

