import math

def perfect_squares(start_num, end_num):
    # Ensure start_num is less than or equal to end_num for correctness
    if start_num > end_num:
        return []

    results = []
    for num in range(start_num, end_num + 1):
        sqrt_val = int(math.sqrt(num))
        if sqrt_val * sqrt_val == num:
            results.append(num)
    return results

# Test the function with the provided test case
assert perfect_squares(1, 30) == [1, 4, 9, 16, 25], "Test failed!"

def swap_List(lst):
    lst[0], lst[-1] = lst[-1], lst[0]
    return lst

def removezero_ip(ip):
    # Split the IP address into its four octets
    octets = ip.split('.')

    # Convert each octet to an integer, strip leading zeros, then convert back to string
    return '.'.join(str(int(octet.lstrip('0'))) if octet.startswith('0') else str(int(octet)) for octet in octets)

