def sum_average(n):
    total = (n * (n + 1)) // 2
    avg = total / n
    return (total, avg)

def is_Even(n):
    # Check if n has a least significant bit of 0 (i.e., it's even)
    return (n & 1) == 0

def is_Even(n):
    # Use the bitwise AND operator (&) with 1
    return (n & 1) == 0
